"use client";

/**
 * CinAssist — Synchronisation (Validierung VOR der Analyse)
 *
 * Zwei Ordner (Kamera-Videos, Ton-WAVs) werden per Referenz importiert; der Matcher
 * (Timecode → Wellenform → Klappe → Dateiname) schlägt Takes vor. Diese Ansicht zeigt
 * jede Zuordnung mit Status, Methode, Offset und Begründung, lässt sie korrigieren
 * (anhängen / abhängen / Offset ±ms / bestätigen / ablehnen) und prüft sie im
 * A/B-Player (Bild + verknüpfter Ton mit Offset — der einzige echte Test).
 * „Analyse starten“ ist gesperrt, solange ein Take `unklar` ist.
 *
 * A/B-Player-Architektur: EIN Referenztakt (die `<video>`), das `<audio>` folgt mit
 * Schwellen-Drift-Korrektur (nie `currentTime` pro Frame; nur bei |Drift| > 80 ms).
 * Das ist ein Kontroll-Werkzeug, NICHT die NLE-Timeline (die hat ihre MasterClock).
 */

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import {
  analyseStarten, connectJobWs, deleteImport, fetchAssets, fetchImporte, fetchTakes, importOrdner,
  linkAnlegen, linkLoeschen, linkOffsetSetzen, mediaUrl, runSync, takeAblehnen, takeBestaetigen,
  takeOhneAudioBestaetigen, vorschauAnfordern,
  type JobUpdate, type MediaAssetDTO, type OrdnerImportDTO, type TakeDTO, type TakeStatus,
} from "@/lib/api";

// ─── Farben / Hilfen ─────────────────────────────────────

const STATUS_FARBE: Record<TakeStatus, string> = {
  sicher: "#5fbf6a", plausibel: "#e0b84a", unklar: "#e2574a", verwaist: "#7a7a7a",
  manuell_bestaetigt: "#7fb2ff", manuell_abgelehnt: "#555",
};
const STATUS_LABEL: Record<TakeStatus, string> = {
  sicher: "sicher", plausibel: "plausibel", unklar: "unklar", verwaist: "verwaist",
  manuell_bestaetigt: "bestätigt", manuell_abgelehnt: "abgelehnt",
};
const BG = "#0f0f10", PANEL = "#1c1c1e", PANEL2 = "#242426", BORDER = "#2a2a2e", TXT = "#cfcfcf", MUTED = "#8a8a8a", ACCENT = "#b9d94a";

const btn = (aktiv = false, farbe = ACCENT): React.CSSProperties => ({
  background: aktiv ? farbe : PANEL2, color: aktiv ? "#000" : TXT, border: `1px solid ${aktiv ? farbe : BORDER}`,
  borderRadius: 6, padding: "5px 10px", fontSize: 12, cursor: "pointer", fontWeight: aktiv ? 600 : 400,
});
const inp: React.CSSProperties = { background: "#111", color: TXT, border: `1px solid ${BORDER}`, borderRadius: 6, padding: "5px 8px", fontSize: 12 };

function fmtOffset(s: number | null | undefined): string {
  if (s === null || s === undefined) return "—";
  return `${s >= 0 ? "+" : "−"}${Math.abs(s).toFixed(3)} s`;
}
function fmtDauer(s: number | null | undefined): string {
  if (!s && s !== 0) return "—";
  const m = Math.floor(s / 60), r = s - m * 60;
  return `${m}:${r.toFixed(1).padStart(4, "0")}`;
}
function gruppenKey(t: TakeDTO): string {
  return `${t.szene ?? "?"}|${t.plan ?? "?"}`;
}
function gruppenLabel(t: TakeDTO): string {
  return `Szene ${t.szene ?? "?"} · Einstellung ${t.plan ?? "?"}`;
}

// ─── A/B-Player ──────────────────────────────────────────

function ABPlayer({ videoUrl, audioUrl, offsetS, audioName }: {
  videoUrl: string | null; audioUrl: string | null; offsetS: number; audioName: string | null;
}) {
  const vRef = useRef<HTMLVideoElement>(null);
  const aRef = useRef<HTMLAudioElement>(null);
  const [mode, setMode] = useState<"A" | "B">("B");
  const [readout, setReadout] = useState({ v: 0, a: 0, drift: 0 });
  const offsetRef = useRef(offsetS);
  offsetRef.current = offsetS;
  const modeRef = useRef(mode);
  modeRef.current = mode;

  useEffect(() => {
    let raf = 0;
    const tick = () => {
      const v = vRef.current, a = aRef.current;
      if (v && a) {
        // offset = audio_start − video_start  ⇒  audio_time = video_time − offset
        const ziel = v.currentTime - offsetRef.current;
        const imBereich = ziel >= 0 && (!isFinite(a.duration) || ziel < a.duration);
        v.muted = modeRef.current === "B";
        a.muted = modeRef.current === "A";
        if (v.paused || v.ended || !imBereich) {
          if (!a.paused) a.pause();
          if (imBereich && Math.abs(a.currentTime - ziel) > 0.03) a.currentTime = ziel;
        } else {
          const drift = a.currentTime - ziel;
          if (a.paused) { a.currentTime = ziel; void a.play().catch(() => {}); }
          else if (Math.abs(drift) > 0.08) a.currentTime = ziel;   // nur bei echtem Drift re-seeken
        }
        setReadout({ v: v.currentTime, a: a.currentTime, drift: imBereich ? a.currentTime - ziel : 0 });
      }
      raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, []);

  if (!videoUrl) return <div style={{ color: MUTED, fontSize: 12 }}>Keine Video-Vorschau — „Vorschau erzeugen“ klicken.</div>;
  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
      <video ref={vRef} src={videoUrl} controls playsInline style={{ width: "100%", maxHeight: 300, background: "#000", borderRadius: 6 }} />
      {audioUrl && <audio ref={aRef} src={audioUrl} preload="auto" />}
      <div style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 12 }}>
        <span style={{ color: MUTED }}>Ton:</span>
        <button style={btn(mode === "A")} onClick={() => setMode("A")}>A — Kamera</button>
        <button style={btn(mode === "B")} onClick={() => setMode("B")} disabled={!audioUrl} title={audioUrl ? "" : "kein verknüpftes Audio"}>
          B — verknüpft{audioName ? ` (${audioName})` : ""}
        </button>
        <span style={{ marginLeft: "auto", color: MUTED, fontVariantNumeric: "tabular-nums" }}>
          Video {readout.v.toFixed(2)} s · Audio {readout.a.toFixed(2)} s · Drift {(readout.drift * 1000).toFixed(0)} ms
        </span>
      </div>
    </div>
  );
}

// ─── Haupt-Panel ─────────────────────────────────────────

export default function SyncPanel({ onAnalyseGestartet }: { onAnalyseGestartet?: () => void }) {
  const [takes, setTakes] = useState<TakeDTO[]>([]);
  const [zaehler, setZaehler] = useState<Partial<Record<TakeStatus, number>>>({});
  const [assets, setAssets] = useState<MediaAssetDTO[]>([]);
  const [importe, setImporte] = useState<OrdnerImportDTO[]>([]);
  const [videoPfad, setVideoPfad] = useState("");
  const [audioPfad, setAudioPfad] = useState("");
  const [auswahl, setAuswahl] = useState<string | null>(null);
  const [filter, setFilter] = useState<TakeStatus | "alle">("alle");
  const [suche, setSuche] = useState("");
  const [zu, setZu] = useState<Set<string>>(new Set());
  const [jobs, setJobs] = useState<Record<string, JobUpdate & { label: string }>>({});
  const [meldung, setMeldung] = useState<string | null>(null);
  const [fehler, setFehler] = useState<string | null>(null);
  const [rattachAudio, setRattachAudio] = useState("");
  const [rattachSuche, setRattachSuche] = useState("");
  const [offsetEntwurf, setOffsetEntwurf] = useState<Record<string, number>>({});
  const [unklarTrotzdem, setUnklarTrotzdem] = useState(false);
  const [busy, setBusy] = useState(false);

  const laden = useCallback(async () => {
    try {
      const [t, i, a] = await Promise.all([fetchTakes(), fetchImporte(), fetchAssets()]);
      setTakes(t.takes); setZaehler(t.status_zaehler); setImporte(i); setAssets(a); setFehler(null);
    } catch (e) { setFehler((e as Error).message); }
  }, []);
  useEffect(() => { void laden(); }, [laden]);

  const verfolgeJob = useCallback((jobId: string, label: string, danach?: () => void) => {
    setJobs((j) => ({ ...j, [jobId]: { status: "wartend", progress: 0, message: "…", label } as JobUpdate & { label: string } }));
    connectJobWs(jobId, (u) => {
      setJobs((j) => ({ ...j, [jobId]: { ...u, label } }));
      if (u.status === "fertig" || u.status === "fehler") {
        setTimeout(() => setJobs((j) => { const c = { ...j }; delete c[jobId]; return c; }), u.status === "fehler" ? 12000 : 2500);
        void laden().then(() => danach?.());
      }
    });
  }, [laden]);

  const aktion = useCallback(async (f: () => Promise<unknown>, ok?: string) => {
    setBusy(true); setFehler(null);
    try { await f(); if (ok) setMeldung(ok); await laden(); }
    catch (e) { setFehler((e as Error).message); }
    finally { setBusy(false); }
  }, [laden]);

  const importieren = (pfad: string, typ: "video" | "audio") => aktion(async () => {
    const r = await importOrdner(pfad.trim(), typ);
    verfolgeJob(r.job_id, `Import ${typ}`);
  });
  const matchen = () => aktion(async () => { const r = await runSync(); verfolgeJob(r.job_id, "Matching"); });
  const analyse = (nurTake?: string) => aktion(async () => {
    const r = await analyseStarten(nurTake ? [nurTake] : undefined, unklarTrotzdem);
    r.gestartet.forEach((g) => verfolgeJob(g.job_id, `Analyse ${g.dateiname}`));
    setMeldung(`${r.gestartet.length} Analyse(n) gestartet${r.uebersprungen.length ? `, ${r.uebersprungen.length} übersprungen` : ""}`);
    onAnalyseGestartet?.();
  });
  const vorschau = (takeId: string) => aktion(async () => {
    const r = await vorschauAnfordern(takeId);
    if (!r.fertig && r.job_id) verfolgeJob(r.job_id, "Vorschau");
  });

  const gefiltert = useMemo(() => {
    const q = suche.trim().toLowerCase();
    return takes.filter((t) => (filter === "alle" || t.status === filter) && (!q ||
      (t.video?.dateiname ?? "").toLowerCase().includes(q) || t.links.some((l) => (l.audio?.dateiname ?? "").toLowerCase().includes(q))));
  }, [takes, filter, suche]);
  const gruppen = useMemo(() => {
    const m = new Map<string, TakeDTO[]>();
    gefiltert.forEach((t) => { const k = gruppenKey(t); if (!m.has(k)) m.set(k, []); m.get(k)!.push(t); });
    return [...m.entries()].sort(([a], [b]) => a.localeCompare(b, undefined, { numeric: true }));
  }, [gefiltert]);
  const sel = takes.find((t) => t.id === auswahl) ?? null;
  const audios = useMemo(() => assets.filter((a) => a.typ === "audio").sort((a, b) => a.dateiname.localeCompare(b.dateiname)), [assets]);
  const rattachListe = useMemo(() => {
    const q = rattachSuche.trim().toLowerCase();
    return q ? audios.filter((a) => a.dateiname.toLowerCase().includes(q) || (a.tc_start ?? "").includes(q)) : audios;
  }, [audios, rattachSuche]);
  const blockiert = (zaehler.unklar ?? 0) > 0;
  const primaerLink = sel?.links.find((l) => l.methode !== "verwaist") ?? sel?.links[0] ?? null;
  const offsetLive = primaerLink ? (offsetEntwurf[primaerLink.id] ?? primaerLink.offset_s) : 0;

  return (
    <div style={{ display: "flex", flexDirection: "column", height: "100%", color: TXT, fontSize: 12, gap: 10 }}>
      {/* Kopf */}
      <div style={{ display: "flex", alignItems: "center", gap: 12, flexWrap: "wrap" }}>
        <span style={{ fontSize: 15, fontWeight: 600, color: ACCENT }}>Synchronisation</span>
        {(["sicher", "plausibel", "unklar", "verwaist", "manuell_bestaetigt", "manuell_abgelehnt"] as TakeStatus[]).map((s) => (
          <button key={s} onClick={() => setFilter(filter === s ? "alle" : s)}
            style={{ ...btn(filter === s, STATUS_FARBE[s]), display: "flex", gap: 6, alignItems: "center" }}>
            <span style={{ width: 8, height: 8, borderRadius: 4, background: STATUS_FARBE[s], display: "inline-block" }} />
            {STATUS_LABEL[s]} {zaehler[s] ?? 0}
          </button>
        ))}
        <input placeholder="Suchen…" value={suche} onChange={(e) => setSuche(e.target.value)} style={{ ...inp, width: 160 }} />
        <div style={{ marginLeft: "auto", display: "flex", gap: 8, alignItems: "center" }}>
          <button style={btn()} onClick={() => void laden()} disabled={busy}>Aktualisieren</button>
          <button style={btn(true)} onClick={() => void matchen()} disabled={busy || assets.length === 0} title="Kaskade Timecode → Wellenform → Klappe → Dateiname">Matching starten</button>
          <label style={{ display: "flex", gap: 4, alignItems: "center", color: MUTED }} title="Unklare Takes werden ohne verknüpften Ton analysiert (Warnung „Transkription auf Kamera-Ton“)">
            <input type="checkbox" checked={unklarTrotzdem} onChange={(e) => setUnklarTrotzdem(e.target.checked)} /> unklar trotzdem
          </label>
          <button style={btn(!blockiert || unklarTrotzdem, "#7fb2ff")} disabled={busy || (blockiert && !unklarTrotzdem) || takes.length === 0}
            onClick={() => void analyse()} title={blockiert ? `${zaehler.unklar} Take(s) unklar — erst entscheiden` : "Clips aus Takes erzeugen + Ingestion (Whisper auf verknüpftem Ton)"}>
            Analyse starten{blockiert ? ` (${zaehler.unklar} unklar)` : ""}
          </button>
        </div>
      </div>

      {/* Import */}
      <div style={{ display: "flex", gap: 8, alignItems: "center", flexWrap: "wrap", background: PANEL, border: `1px solid ${BORDER}`, borderRadius: 8, padding: 8 }}>
        <span style={{ color: MUTED }}>Ordner per Referenz (keine Kopie):</span>
        <input placeholder="/Volumes/…/ROHMAT_VIDEO" value={videoPfad} onChange={(e) => setVideoPfad(e.target.value)} style={{ ...inp, width: 260 }} />
        <button style={btn()} disabled={busy || !videoPfad.trim()} onClick={() => void importieren(videoPfad, "video")}>Video importieren</button>
        <input placeholder="/Volumes/…/ROHMAT_AUDIO" value={audioPfad} onChange={(e) => setAudioPfad(e.target.value)} style={{ ...inp, width: 260 }} />
        <button style={btn()} disabled={busy || !audioPfad.trim()} onClick={() => void importieren(audioPfad, "audio")}>Audio importieren</button>
        <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginLeft: 8 }}>
          {importe.map((i) => (
            <span key={i.id} title={`${i.pfad}\n${i.fehler ?? ""}`} style={{ background: PANEL2, border: `1px solid ${i.volume_gemountet ? BORDER : "#e2574a"}`, borderRadius: 6, padding: "3px 8px", display: "flex", gap: 6, alignItems: "center" }}>
              <b style={{ color: i.typ === "video" ? "#7fb2ff" : "#e0b84a" }}>{i.typ}</b> {i.pfad.split("/").slice(-2).join("/")} · {i.anzahl_dateien} Dateien
              {i.anzahl_ignoriert > 0 && <span style={{ color: MUTED }}>({i.anzahl_ignoriert} ignoriert)</span>}
              {!i.volume_gemountet && <span style={{ color: "#e2574a" }}>Volume nicht gemountet</span>}
              {i.status !== "fertig" && <span style={{ color: MUTED }}>{i.status}</span>}
              <button title="Import aus DB entfernen (Dateien bleiben)" style={{ background: "transparent", border: "none", color: MUTED, cursor: "pointer" }}
                onClick={() => void aktion(() => deleteImport(i.id))}>×</button>
            </span>
          ))}
        </div>
      </div>

      {(Object.keys(jobs).length > 0 || meldung || fehler) && (
        <div style={{ display: "flex", gap: 10, flexWrap: "wrap", alignItems: "center" }}>
          {Object.entries(jobs).map(([id, j]) => (
            <span key={id} style={{ background: PANEL2, borderRadius: 6, padding: "3px 8px", color: j.status === "fehler" ? "#e2574a" : TXT }}>
              {j.label}: {j.progress}% — {j.message}
            </span>
          ))}
          {meldung && <span style={{ color: ACCENT }}>{meldung} <button style={{ background: "none", border: "none", color: MUTED, cursor: "pointer" }} onClick={() => setMeldung(null)}>×</button></span>}
          {fehler && <span style={{ color: "#e2574a" }}>{fehler} <button style={{ background: "none", border: "none", color: MUTED, cursor: "pointer" }} onClick={() => setFehler(null)}>×</button></span>}
        </div>
      )}

      {/* Hauptbereich */}
      <div style={{ display: "flex", gap: 10, flex: 1, minHeight: 0 }}>
        {/* Liste */}
        <div style={{ flex: "0 0 46%", overflowY: "auto", background: PANEL, border: `1px solid ${BORDER}`, borderRadius: 8 }}>
          {takes.length === 0 && <div style={{ padding: 16, color: MUTED }}>Noch keine Takes — Ordner importieren, dann „Matching starten“.</div>}
          {gruppen.map(([k, liste]) => {
            const offen = !zu.has(k);
            return (
              <div key={k}>
                <div onClick={() => setZu((s) => { const n = new Set(s); n.has(k) ? n.delete(k) : n.add(k); return n; })}
                  style={{ padding: "6px 10px", background: "#18181a", borderBottom: `1px solid ${BORDER}`, cursor: "pointer", display: "flex", gap: 8, position: "sticky", top: 0 }}>
                  <span style={{ color: MUTED }}>{offen ? "▾" : "▸"}</span><b>{gruppenLabel(liste[0])}</b><span style={{ color: MUTED }}>{liste.length} Take(s)</span>
                </div>
                {offen && liste.map((t) => {
                  const primaer = t.links.find((l) => l.methode !== "verwaist") ?? null;
                  const warn = t.warnungen.length + t.links.reduce((n, l) => n + l.warnungen.length, 0);
                  const aktiv = t.id === auswahl;
                  return (
                    <div key={t.id} onClick={() => { setAuswahl(t.id); setRattachAudio(""); }}
                      style={{ padding: "6px 10px", borderBottom: `1px solid #1a1a1c`, cursor: "pointer", background: aktiv ? "#2a2f1e" : "transparent", display: "grid", gridTemplateColumns: "10px 1fr auto", gap: 8, alignItems: "center" }}>
                      <span title={STATUS_LABEL[t.status]} style={{ width: 10, height: 10, borderRadius: 5, background: STATUS_FARBE[t.status] }} />
                      <div style={{ minWidth: 0 }}>
                        <div style={{ display: "flex", gap: 8, alignItems: "baseline" }}>
                          <span style={{ fontWeight: 600, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{t.video ? t.video.dateiname : "— (Audio ohne Bild)"}</span>
                          {t.video && <span style={{ color: MUTED, fontVariantNumeric: "tabular-nums" }}>{t.video.tc_start ?? "kein TC"} · {fmtDauer(t.video.dauer_s)}</span>}
                          {t.clip_id && <span style={{ color: "#7fb2ff" }} title={`Clip ${t.clip_status}`}>● {t.clip_status}</span>}
                        </div>
                        {t.links.map((l) => (
                          <div key={l.id} style={{ color: l.methode === "verwaist" ? MUTED : TXT, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>
                            ♪ {l.audio?.dateiname ?? l.audio_asset_id}
                            {l.methode !== "verwaist" && <span style={{ color: MUTED }}> · {l.methode} · {fmtOffset(l.offset_s)} · {(l.konfidenz * 100).toFixed(0)} %</span>}
                            {l.audio?.unbekannte_markierung && <span style={{ color: "#e0b84a" }} title="unbekannte Markierung — nicht interpretiert"> [{l.audio.unbekannte_markierung}?]</span>}
                          </div>
                        ))}
                        {t.status === "unklar" && <div style={{ color: "#e2574a" }}>{t.kandidaten.length} Kandidat(en) — manuell entscheiden</div>}
                      </div>
                      <span style={{ color: warn ? "#e0b84a" : MUTED, whiteSpace: "nowrap" }} title="Warnungen">{warn ? `⚠ ${warn}` : ""}{primaer?.bestaetigt ? " ✓" : ""}</span>
                    </div>
                  );
                })}
              </div>
            );
          })}
        </div>

        {/* Detail */}
        <div style={{ flex: 1, overflowY: "auto", background: PANEL, border: `1px solid ${BORDER}`, borderRadius: 8, padding: 12, display: "flex", flexDirection: "column", gap: 10 }}>
          {!sel && <div style={{ color: MUTED }}>Take auswählen.</div>}
          {sel && (<>
            <div style={{ display: "flex", gap: 10, alignItems: "center", flexWrap: "wrap" }}>
              <span style={{ background: STATUS_FARBE[sel.status], color: "#000", borderRadius: 4, padding: "2px 8px", fontWeight: 600 }}>{STATUS_LABEL[sel.status]}</span>
              <b>{sel.video?.dateiname ?? "Audio ohne Bild"}</b>
              {sel.video && <span style={{ color: MUTED }}>TC {sel.video.tc_start ?? "—"} ({sel.video.tc_quelle}{sel.video.ltc_kanal !== null ? `, Kanal ${sel.video.ltc_kanal}` : ""}) · {sel.video.fps ?? "?"} fps · {fmtDauer(sel.video.dauer_s)}{sel.video.scratch_kanal === null ? " · kein Scratch" : ` · Scratch Kanal ${sel.video.scratch_kanal}`}</span>}
              <div style={{ marginLeft: "auto", display: "flex", gap: 6, flexWrap: "wrap" }}>
                <button style={btn()} disabled={busy} onClick={() => void vorschau(sel.id)}>Vorschau erzeugen</button>
                <button style={btn(false, "#5fbf6a")} disabled={busy || sel.status === "manuell_bestaetigt"} onClick={() => void aktion(() => takeBestaetigen(sel.id), "Take bestätigt")}>Bestätigen</button>
                {sel.video && <button style={btn()} disabled={busy} title="Bewusst ohne Ton freigeben (Transkription auf Kamera-Ton)" onClick={() => void aktion(() => takeOhneAudioBestaetigen(sel.id), "Ohne Ton freigegeben")}>Ohne Ton freigeben</button>}
                <button style={btn(false, "#e2574a")} disabled={busy || sel.status === "manuell_abgelehnt"} onClick={() => void aktion(() => takeAblehnen(sel.id), "Take abgelehnt")}>Ablehnen</button>
                {sel.video && <button style={btn(false, "#7fb2ff")} disabled={busy || sel.status === "unklar" || sel.status === "manuell_abgelehnt"} onClick={() => void analyse(sel.id)}>Nur diesen Take analysieren</button>}
              </div>
            </div>

            {/* A/B-Player */}
            <ABPlayer videoUrl={mediaUrl(sel.vorschau_video_url)} audioUrl={mediaUrl(primaerLink?.vorschau_audio_url)} offsetS={offsetLive} audioName={primaerLink?.audio?.dateiname ?? null} />

            {/* Links */}
            {sel.links.map((l) => {
              const entwurf = offsetEntwurf[l.id] ?? l.offset_s;
              const geaendert = Math.abs(entwurf - l.offset_s) > 1e-6;
              return (
                <div key={l.id} style={{ background: PANEL2, borderRadius: 8, padding: 10, display: "flex", flexDirection: "column", gap: 6 }}>
                  <div style={{ display: "flex", gap: 8, alignItems: "center", flexWrap: "wrap" }}>
                    <b>♪ {l.audio?.dateiname}</b>
                    {l.audio && <span style={{ color: MUTED }}>TC {l.audio.tc_start ?? "—"} ({l.audio.tc_quelle}) · {l.audio.kanaele} Kanäle · Transkription Kanal {l.kanal_fuer_transkription}{l.audio.ixml && Array.isArray((l.audio.ixml as { tracks?: { index: number; name: string }[] }).tracks) ? ` („${((l.audio.ixml as { tracks: { index: number; name: string }[] }).tracks.find((t) => t.index === l.kanal_fuer_transkription + 1)?.name ?? "?")}“)` : ""} · {fmtDauer(l.audio.dauer_s)}</span>}
                    <span style={{ marginLeft: "auto", color: MUTED }}>{l.methode} · Konfidenz {(l.konfidenz * 100).toFixed(0)} %{l.bestaetigt ? " · ✓ bestätigt" : ""}</span>
                    <button style={btn(false, "#e2574a")} disabled={busy} title="Audio von diesem Take abhängen" onClick={() => void aktion(() => linkLoeschen(l.id), "Audio abgehängt")}>Abhängen</button>
                  </div>
                  <div style={{ color: TXT, lineHeight: 1.5 }}>{l.begruendung}</div>
                  {l.warnungen.map((w, i) => <div key={i} style={{ color: "#e0b84a" }}>⚠ {w}</div>)}
                  {l.methode !== "verwaist" && (
                    <div style={{ display: "flex", gap: 6, alignItems: "center", flexWrap: "wrap" }}>
                      <span style={{ color: MUTED }}>Offset (Audio − Video):</span>
                      {[-1, -0.1, -0.01].map((d) => <button key={d} style={btn()} onClick={() => setOffsetEntwurf((o) => ({ ...o, [l.id]: +(entwurf + d).toFixed(3) }))}>{d} s</button>)}
                      <input type="number" step="0.001" value={entwurf} onChange={(e) => setOffsetEntwurf((o) => ({ ...o, [l.id]: parseFloat(e.target.value) || 0 }))} style={{ ...inp, width: 100, fontVariantNumeric: "tabular-nums" }} />
                      {[0.01, 0.1, 1].map((d) => <button key={d} style={btn()} onClick={() => setOffsetEntwurf((o) => ({ ...o, [l.id]: +(entwurf + d).toFixed(3) }))}>+{d} s</button>)}
                      <button style={btn(geaendert, "#7fb2ff")} disabled={!geaendert || busy} onClick={() => void aktion(async () => { await linkOffsetSetzen(l.id, entwurf); setOffsetEntwurf((o) => { const c = { ...o }; delete c[l.id]; return c; }); }, "Offset gespeichert")}>Speichern</button>
                      {geaendert && <button style={btn()} onClick={() => setOffsetEntwurf((o) => { const c = { ...o }; delete c[l.id]; return c; })}>Zurücksetzen</button>}
                    </div>
                  )}
                </div>
              );
            })}

            {/* Kandidaten (unklar) */}
            {sel.kandidaten.length > 0 && (
              <div style={{ background: PANEL2, borderRadius: 8, padding: 10 }}>
                <b style={{ color: "#e2574a" }}>Kandidaten — nicht automatisch entschieden</b>
                {sel.kandidaten.map((k, i) => (
                  <div key={i} style={{ display: "flex", gap: 8, alignItems: "center", padding: "4px 0", borderTop: i ? `1px solid ${BORDER}` : "none" }}>
                    <div style={{ flex: 1 }}>
                      <div>♪ {k.audio_dateiname} ↔ {k.video_dateiname} · Überlappung {(k.ueberlappung_ratio * 100).toFixed(0)} % ({k.ueberlappung_s.toFixed(1)} s) · Offset {fmtOffset(k.offset_s)}</div>
                      <div style={{ color: MUTED }}>{k.begruendung}</div>
                    </div>
                    {sel.video && k.video_asset_id === sel.video_asset_id && (
                      <button style={btn(true, "#7fb2ff")} disabled={busy} onClick={() => void aktion(() => linkAnlegen(sel.id, k.audio_asset_id, k.offset_s), "Audio zugeordnet")}>Dieses Audio zuordnen</button>
                    )}
                  </div>
                ))}
              </div>
            )}

            {/* Rattacher */}
            {sel.video && (
              <div style={{ background: PANEL2, borderRadius: 8, padding: 10, display: "flex", gap: 8, alignItems: "center", flexWrap: "wrap" }}>
                <span style={{ color: MUTED }}>Anderes Audio anhängen:</span>
                <input placeholder="Audio suchen…" value={rattachSuche} onChange={(e) => setRattachSuche(e.target.value)} style={{ ...inp, width: 160 }} />
                <select value={rattachAudio} onChange={(e) => setRattachAudio(e.target.value)} style={{ ...inp, maxWidth: 360 }}>
                  <option value="">— wählen —</option>
                  {rattachListe.map((a) => <option key={a.id} value={a.id}>{a.dateiname} · {a.tc_start ?? "kein TC"} · {fmtDauer(a.dauer_s)}</option>)}
                </select>
                <button style={btn(!!rattachAudio, "#7fb2ff")} disabled={!rattachAudio || busy} title="Offset aus Timecode, sonst 0 s (im A/B-Player prüfen)"
                  onClick={() => void aktion(async () => { await linkAnlegen(sel.id, rattachAudio, null); setRattachAudio(""); }, "Audio angehängt (methode: manuell)")}>Anhängen</button>
              </div>
            )}

            {/* Warnungen */}
            {sel.warnungen.length > 0 && (
              <div style={{ background: PANEL2, borderRadius: 8, padding: 10 }}>
                <b>Hinweise</b>
                {sel.warnungen.map((w, i) => <div key={i} style={{ color: w.startsWith("Mehrdeutig") ? "#e2574a" : "#e0b84a", padding: "2px 0" }}>⚠ {w}</div>)}
              </div>
            )}
            {sel.video && sel.video.warnungen.length > 0 && (
              <div style={{ color: MUTED }}>{sel.video.warnungen.map((w, i) => <div key={i}>· {w}</div>)}</div>
            )}
          </>)}
        </div>
      </div>
    </div>
  );
}

toolUseResult.content:
"use client";

/**
 * CinAssist — Synchronisation (Validierung VOR der Analyse)
 *
 * Zwei Ordner (Kamera-Videos, Ton-WAVs) werden per Referenz importiert; der Matcher
 * (Timecode → Wellenform → Klappe → Dateiname) schlägt Takes vor. Diese Ansicht zeigt
 * jede Zuordnung mit Status, Methode, Offset und Begründung, lässt sie korrigieren
 * (anhängen / abhängen / Offset ±ms / bestätigen / ablehnen) und prüft sie im
 * A/B-Player (Bild + verknüpfter Ton mit Offset — der einzige echte Test).
 * „Analyse starten“ ist gesperrt, solange ein Take `unklar` ist.
 *
 * A/B-Player-Architektur: EIN Referenztakt (die `<video>`), das `<audio>` folgt mit
 * Schwellen-Drift-Korrektur (nie `currentTime` pro Frame; nur bei |Drift| > 80 ms).
 * Das ist ein Kontroll-Werkzeug, NICHT die NLE-Timeline (die hat ihre MasterClock).
 */

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import {
  analyseStarten, connectJobWs, deleteImport, fetchAssets, fetchImporte, fetchTakes, importOrdner,
  linkAnlegen, linkLoeschen, linkOffsetSetzen, mediaUrl, runSync, takeAblehnen, takeBestaetigen,
  takeOhneAudioBestaetigen, vorschauAnfordern,
  type JobUpdate, type MediaAssetDTO, type OrdnerImportDTO, type TakeDTO, type TakeStatus,
} from "@/lib/api";

// ─── Farben / Hilfen ─────────────────────────────────────

const STATUS_FARBE: Record<TakeStatus, string> = {
  sicher: "#5fbf6a", plausibel: "#e0b84a", unklar: "#e2574a", verwaist: "#7a7a7a",
  manuell_bestaetigt: "#7fb2ff", manuell_abgelehnt: "#555",
};
const STATUS_LABEL: Record<TakeStatus, string> = {
  sicher: "sicher", plausibel: "plausibel", unklar: "unklar", verwaist: "verwaist",
  manuell_bestaetigt: "bestätigt", manuell_abgelehnt: "abgelehnt",
};
const BG = "#0f0f10", PANEL = "#1c1c1e", PANEL2 = "#242426", BORDER = "#2a2a2e", TXT = "#cfcfcf", MUTED = "#8a8a8a", ACCENT = "#b9d94a";

const btn = (aktiv = false, farbe = ACCENT): React.CSSProperties => ({
  background: aktiv ? farbe : PANEL2, color: aktiv ? "#000" : TXT, border: `1px solid ${aktiv ? farbe : BORDER}`,
  borderRadius: 6, padding: "5px 10px", fontSize: 12, cursor: "pointer", fontWeight: aktiv ? 600 : 400,
});
const inp: React.CSSProperties = { background: "#111", color: TXT, border: `1px solid ${BORDER}`, borderRadius: 6, padding: "5px 8px", fontSize: 12 };

function fmtOffset(s: number | null | undefined): string {
  if (s === null || s === undefined) return "—";
  return `${s >= 0 ? "+" : "−"}${Math.abs(s).toFixed(3)} s`;
}
function fmtDauer(s: number | null | undefined): string {
  if (!s && s !== 0) return "—";
  const m = Math.floor(s / 60), r = s - m * 60;
  return `${m}:${r.toFixed(1).padStart(4, "0")}`;
}
function gruppenKey(t: TakeDTO): string {
  return `${t.szene ?? "?"}|${t.plan ?? "?"}`;
}
function gruppenLabel(t: TakeDTO): string {
  return `Szene ${t.szene ?? "?"} · Einstellung ${t.plan ?? "?"}`;
}

// ─── A/B-Player ──────────────────────────────────────────

function ABPlayer({ videoUrl, audioUrl, offsetS, audioName }: {
  videoUrl: string | null; audioUrl: string | null; offsetS: number; audioName: string | null;
}) {
  const vRef = useRef<HTMLVideoElement>(null);
  const aRef = useRef<HTMLAudioElement>(null);
  const [mode, setMode] = useState<"A" | "B">("B");
  const [readout, setReadout] = useState({ v: 0, a: 0, drift: 0 });
  const offsetRef = useRef(offsetS);
  offsetRef.current = offsetS;
  const modeRef = useRef(mode);
  modeRef.current = mode;

  useEffect(() => {
    let raf = 0;
    const tick = () => {
      const v = vRef.current, a = aRef.current;
      if (v && a) {
        // offset = audio_start − video_start  ⇒  audio_time = video_time − offset
        const ziel = v.currentTime - offsetRef.current;
        const imBereich = ziel >= 0 && (!isFinite(a.duration) || ziel < a.duration);
        v.muted = modeRef.current === "B";
        a.muted = modeRef.current === "A";
        if (v.paused || v.ended || !imBereich) {
          if (!a.paused) a.pause();
          if (imBereich && Math.abs(a.currentTime - ziel) > 0.03) a.currentTime = ziel;
        } else {
          const drift = a.currentTime - ziel;
          if (a.paused) { a.currentTime = ziel; void a.play().catch(() => {}); }
          else if (Math.abs(drift) > 0.08) a.currentTime = ziel;   // nur bei echtem Drift re-seeken
        }
        setReadout({ v: v.currentTime, a: a.currentTime, drift: imBereich ? a.currentTime - ziel : 0 });
      }
      raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, []);

  if (!videoUrl) return <div style={{ color: MUTED, fontSize: 12 }}>Keine Video-Vorschau — „Vorschau erzeugen“ klicken.</div>;
  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
      <video ref={vRef} src={videoUrl} controls playsInline style={{ width: "100%", maxHeight: 300, background: "#000", borderRadius: 6 }} />
      {audioUrl && <audio ref={aRef} src={audioUrl} preload="auto" />}
      <div style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 12 }}>
        <span style={{ color: MUTED }}>Ton:</span>
        <button style={btn(mode === "A")} onClick={() => setMode("A")}>A — Kamera</button>
        <button style={btn(mode === "B")} onClick={() => setMode("B")} disabled={!audioUrl} title={audioUrl ? "" : "kein verknüpftes Audio"}>
          B — verknüpft{audioName ? ` (${audioName})` : ""}
        </button>
        <span style={{ marginLeft: "auto", color: MUTED, fontVariantNumeric: "tabular-nums" }}>
          Video {readout.v.toFixed(2)} s · Audio {readout.a.toFixed(2)} s · Drift {(readout.drift * 1000).toFixed(0)} ms
        </span>
      </div>
    </div>
  );
}

// ─── Haupt-Panel ─────────────────────────────────────────

export default function SyncPanel({ onAnalyseGestartet }: { onAnalyseGestartet?: () => void }) {
  const [takes, setTakes] = useState<TakeDTO[]>([]);
  const [zaehler, setZaehler] = useState<Partial<Record<TakeStatus, number>>>({});
  const [assets, setAssets] = useState<MediaAssetDTO[]>([]);
  const [importe, setImporte] = useState<OrdnerImportDTO[]>([]);
  const [videoPfad, setVideoPfad] = useState("");
  const [audioPfad, setAudioPfad] = useState("");
  const [auswahl, setAuswahl] = useState<string | null>(null);
  const [filter, setFilter] = useState<TakeStatus | "alle">("alle");
  const [suche, setSuche] = useState("");
  const [zu, setZu] = useState<Set<string>>(new Set());
  const [jobs, setJobs] = useState<Record<string, JobUpdate & { label: string }>>({});
  const [meldung, setMeldung] = useState<string | null>(null);
  const [fehler, setFehler] = useState<string | null>(null);
  const [rattachAudio, setRattachAudio] = useState("");
  const [rattachSuche, setRattachSuche] = useState("");
  const [offsetEntwurf, setOffsetEntwurf] = useState<Record<string, number>>({});
  const [unklarTrotzdem, setUnklarTrotzdem] = useState(false);
  const [busy, setBusy] = useState(false);

  const laden = useCallback(async () => {
    try {
      const [t, i, a] = await Promise.all([fetchTakes(), fetchImporte(), fetchAssets()]);
      setTakes(t.takes); setZaehler(t.status_zaehler); setImporte(i); setAssets(a); setFehler(null);
    } catch (e) { setFehler((e as Error).message); }
  }, []);
  useEffect(() => { void laden(); }, [laden]);

  const verfolgeJob = useCallback((jobId: string, label: string, danach?: () => void) => {
    setJobs((j) => ({ ...j, [jobId]: { status: "wartend", progress: 0, message: "…", label } as JobUpdate & { label: string } }));
    connectJobWs(jobId, (u) => {
      setJobs((j) => ({ ...j, [jobId]: { ...u, label } }));
      if (u.status === "fertig" || u.status === "fehler") {
        setTimeout(() => setJobs((j) => { const c = { ...j }; delete c[jobId]; return c; }), u.status === "fehler" ? 12000 : 2500);
        void laden().then(() => danach?.());
      }
    });
  }, [laden]);

  const aktion = useCallback(async (f: () => Promise<unknown>, ok?: string) => {
    setBusy(true); setFehler(null);
    try { await f(); if (ok) setMeldung(ok); await laden(); }
    catch (e) { setFehler((e as Error).message); }
    finally { setBusy(false); }
  }, [laden]);

  const importieren = (pfad: string, typ: "video" | "audio") => aktion(async () => {
    const r = await importOrdner(pfad.trim(), typ);
    verfolgeJob(r.job_id, `Import ${typ}`);
  });
  const matchen = () => aktion(async () => { const r = await runSync(); verfolgeJob(r.job_id, "Matching"); });
  const analyse = (nurTake?: string) => aktion(async () => {
    const r = await analyseStarten(nurTake ? [nurTake] : undefined, unklarTrotzdem);
    r.gestartet.forEach((g) => verfolgeJob(g.job_id, `Analyse ${g.dateiname}`));
    setMeldung(`${r.gestartet.length} Analyse(n) gestartet${r.uebersprungen.length ? `, ${r.uebersprungen.length} übersprungen` : ""}`);
    onAnalyseGestartet?.();
  });
  const vorschau = (takeId: string) => aktion(async () => {
    const r = await vorschauAnfordern(takeId);
    if (!r.fertig && r.job_id) verfolgeJob(r.job_id, "Vorschau");
  });

  const gefiltert = useMemo(() => {
    const q = suche.trim().toLowerCase();
    return takes.filter((t) => (filter === "alle" || t.status === filter) && (!q ||
      (t.video?.dateiname ?? "").toLowerCase().includes(q) || t.links.some((l) => (l.audio?.dateiname ?? "").toLowerCase().includes(q))));
  }, [takes, filter, suche]);
  const gruppen = useMemo(() => {
    const m = new Map<string, TakeDTO[]>();
    gefiltert.forEach((t) => { const k = gruppenKey(t); if (!m.has(k)) m.set(k, []); m.get(k)!.push(t); });
    return [...m.entries()].sort(([a], [b]) => a.localeCompare(b, undefined, { numeric: true }));
  }, [gefiltert]);
  const sel = takes.find((t) => t.id === auswahl) ?? null;
  const audios = useMemo(() => assets.filter((a) => a.typ === "audio").sort((a, b) => a.dateiname.localeCompare(b.dateiname)), [assets]);
  const rattachListe = useMemo(() => {
    const q = rattachSuche.trim().toLowerCase();
    return q ? audios.filter((a) => a.dateiname.toLowerCase().includes(q) || (a.tc_start ?? "").includes(q)) : audios;
  }, [audios, rattachSuche]);
  const blockiert = (zaehler.unklar ?? 0) > 0;
  const primaerLink = sel?.links.find((l) => l.methode !== "verwaist") ?? sel?.links[0] ?? null;
  const offsetLive = primaerLink ? (offsetEntwurf[primaerLink.id] ?? primaerLink.offset_s) : 0;

  return (
    <div style={{ display: "flex", flexDirection: "column", height: "100%", color: TXT, fontSize: 12, gap: 10 }}>
      {/* Kopf */}
      <div style={{ display: "flex", alignItems: "center", gap: 12, flexWrap: "wrap" }}>
        <span style={{ fontSize: 15, fontWeight: 600, color: ACCENT }}>Synchronisation</span>
        {(["sicher", "plausibel", "unklar", "verwaist", "manuell_bestaetigt", "manuell_abgelehnt"] as TakeStatus[]).map((s) => (
          <button key={s} onClick={() => setFilter(filter === s ? "alle" : s)}
            style={{ ...btn(filter === s, STATUS_FARBE[s]), display: "flex", gap: 6, alignItems: "center" }}>
            <span style={{ width: 8, height: 8, borderRadius: 4, background: STATUS_FARBE[s], display: "inline-block" }} />
            {STATUS_LABEL[s]} {zaehler[s] ?? 0}
          </button>
        ))}
        <input placeholder="Suchen…" value={suche} onChange={(e) => setSuche(e.target.value)} style={{ ...inp, width: 160 }} />
        <div style={{ marginLeft: "auto", display: "flex", gap: 8, alignItems: "center" }}>
          <button style={btn()} onClick={() => void laden()} disabled={busy}>Aktualisieren</button>
          <button style={btn(true)} onClick={() => void matchen()} disabled={busy || assets.length === 0} title="Kaskade Timecode → Wellenform → Klappe → Dateiname">Matching starten</button>
          <label style={{ display: "flex", gap: 4, alignItems: "center", color: MUTED }} title="Unklare Takes werden ohne verknüpften Ton analysiert (Warnung „Transkription auf Kamera-Ton“)">
            <input type="checkbox" checked={unklarTrotzdem} onChange={(e) => setUnklarTrotzdem(e.target.checked)} /> unklar trotzdem
          </label>
          <button style={btn(!blockiert || unklarTrotzdem, "#7fb2ff")} disabled={busy || (blockiert && !unklarTrotzdem) || takes.length === 0}
            onClick={() => void analyse()} title={blockiert ? `${zaehler.unklar} Take(s) unklar — erst entscheiden` : "Clips aus Takes erzeugen + Ingestion (Whisper auf verknüpftem Ton)"}>
            Analyse starten{blockiert ? ` (${zaehler.unklar} unklar)` : ""}
          </button>
        </div>
      </div>

      {/* Import */}
      <div style={{ display: "flex", gap: 8, alignItems: "center", flexWrap: "wrap", background: PANEL, border: `1px solid ${BORDER}`, borderRadius: 8, padding: 8 }}>
        <span style={{ color: MUTED }}>Ordner per Referenz (keine Kopie):</span>
        <input placeholder="/Volumes/…/ROHMAT_VIDEO" value={videoPfad} onChange={(e) => setVideoPfad(e.target.value)} style={{ ...inp, width: 260 }} />
        <button style={btn()} disabled={busy || !videoPfad.trim()} onClick={() => void importieren(videoPfad, "video")}>Video importieren</button>
        <input placeholder="/Volumes/…/ROHMAT_AUDIO" value={audioPfad} onChange={(e) => setAudioPfad(e.target.value)} style={{ ...inp, width: 260 }} />
        <button style={btn()} disabled={busy || !audioPfad.trim()} onClick={() => void importieren(audioPfad, "audio")}>Audio importieren</button>
        <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginLeft: 8 }}>
          {importe.map((i) => (
            <span key={i.id} title={`${i.pfad}\n${i.fehler ?? ""}`} style={{ background: PANEL2, border: `1px solid ${i.volume_gemountet ? BORDER : "#e2574a"}`, borderRadius: 6, padding: "3px 8px", display: "flex", gap: 6, alignItems: "center" }}>
              <b style={{ color: i.typ === "video" ? "#7fb2ff" : "#e0b84a" }}>{i.typ}</b> {i.pfad.split("/").slice(-2).join("/")} · {i.anzahl_dateien} Dateien
              {i.anzahl_ignoriert > 0 && <span style={{ color: MUTED }}>({i.anzahl_ignoriert} ignoriert)</span>}
              {!i.volume_gemountet && <span style={{ color: "#e2574a" }}>Volume nicht gemountet</span>}
              {i.status !== "fertig" && <span style={{ color: MUTED }}>{i.status}</span>}
              <button title="Import aus DB entfernen (Dateien bleiben)" style={{ background: "transparent", border: "none", color: MUTED, cursor: "pointer" }}
                onClick={() => void aktion(() => deleteImport(i.id))}>×</button>
            </span>
          ))}
        </div>
      </div>

      {(Object.keys(jobs).length > 0 || meldung || fehler) && (
        <div style={{ display: "flex", gap: 10, flexWrap: "wrap", alignItems: "center" }}>
          {Object.entries(jobs).map(([id, j]) => (
            <span key={id} style={{ background: PANEL2, borderRadius: 6, padding: "3px 8px", color: j.status === "fehler" ? "#e2574a" : TXT }}>
              {j.label}: {j.progress}% — {j.message}
            </span>
          ))}
          {meldung && <span style={{ color: ACCENT }}>{meldung} <button style={{ background: "none", border: "none", color: MUTED, cursor: "pointer" }} onClick={() => setMeldung(null)}>×</button></span>}
          {fehler && <span style={{ color: "#e2574a" }}>{fehler} <button style={{ background: "none", border: "none", color: MUTED, cursor: "pointer" }} onClick={() => setFehler(null)}>×</button></span>}
        </div>
      )}

      {/* Hauptbereich */}
      <div style={{ display: "flex", gap: 10, flex: 1, minHeight: 0 }}>
        {/* Liste */}
        <div style={{ flex: "0 0 46%", overflowY: "auto", background: PANEL, border: `1px solid ${BORDER}`, borderRadius: 8 }}>
          {takes.length === 0 && <div style={{ padding: 16, color: MUTED }}>Noch keine Takes — Ordner importieren, dann „Matching starten“.</div>}
          {gruppen.map(([k, liste]) => {
            const offen = !zu.has(k);
            return (
              <div key={k}>
                <div onClick={() => setZu((s) => { const n = new Set(s); n.has(k) ? n.delete(k) : n.add(k); return n; })}
                  style={{ padding: "6px 10px", background: "#18181a", borderBottom: `1px solid ${BORDER}`, cursor: "pointer", display: "flex", gap: 8, position: "sticky", top: 0 }}>
                  <span style={{ color: MUTED }}>{offen ? "▾" : "▸"}</span><b>{gruppenLabel(liste[0])}</b><span style={{ color: MUTED }}>{liste.length} Take(s)</span>
                </div>
                {offen && liste.map((t) => {
                  const primaer = t.links.find((l) => l.methode !== "verwaist") ?? null;
                  const warn = t.warnungen.length + t.links.reduce((n, l) => n + l.warnungen.length, 0);
                  const aktiv = t.id === auswahl;
                  return (
                    <div key={t.id} onClick={() => { setAuswahl(t.id); setRattachAudio(""); }}
                      style={{ padding: "6px 10px", borderBottom: `1px solid #1a1a1c`, cursor: "pointer", background: aktiv ? "#2a2f1e" : "transparent", display: "grid", gridTemplateColumns: "10px 1fr auto", gap: 8, alignItems: "center" }}>
                      <span title={STATUS_LABEL[t.status]} style={{ width: 10, height: 10, borderRadius: 5, background: STATUS_FARBE[t.status] }} />
                      <div style={{ minWidth: 0 }}>
                        <div style={{ display: "flex", gap: 8, alignItems: "baseline" }}>
                          <span style={{ fontWeight: 600, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{t.video ? t.video.dateiname : "— (Audio ohne Bild)"}</span>
                          {t.video && <span style={{ color: MUTED, fontVariantNumeric: "tabular-nums" }}>{t.video.tc_start ?? "kein TC"} · {fmtDauer(t.video.dauer_s)}</span>}
                          {t.clip_id && <span style={{ color: "#7fb2ff" }} title={`Clip ${t.clip_status}`}>● {t.clip_status}</span>}
                        </div>
                        {t.links.map((l) => (
                          <div key={l.id} style={{ color: l.methode === "verwaist" ? MUTED : TXT, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>
                            ♪ {l.audio?.dateiname ?? l.audio_asset_id}
                            {l.methode !== "verwaist" && <span style={{ color: MUTED }}> · {l.methode} · {fmtOffset(l.offset_s)} · {(l.konfidenz * 100).toFixed(0)} %</span>}
                            {l.audio?.unbekannte_markierung && <span style={{ color: "#e0b84a" }} title="unbekannte Markierung — nicht interpretiert"> [{l.audio.unbekannte_markierung}?]</span>}
                          </div>
                        ))}
                        {t.status === "unklar" && <div style={{ color: "#e2574a" }}>{t.kandidaten.length} Kandidat(en) — manuell entscheiden</div>}
                      </div>
                      <span style={{ color: warn ? "#e0b84a" : MUTED, whiteSpace: "nowrap" }} title="Warnungen">{warn ? `⚠ ${warn}` : ""}{primaer?.bestaetigt ? " ✓" : ""}</span>
                    </div>
                  );
                })}
              </div>
            );
          })}
        </div>

        {/* Detail */}
        <div style={{ flex: 1, overflowY: "auto", background: PANEL, border: `1px solid ${BORDER}`, borderRadius: 8, padding: 12, display: "flex", flexDirection: "column", gap: 10 }}>
          {!sel && <div style={{ color: MUTED }}>Take auswählen.</div>}
          {sel && (<>
            <div style={{ display: "flex", gap: 10, alignItems: "center", flexWrap: "wrap" }}>
              <span style={{ background: STATUS_FARBE[sel.status], color: "#000", borderRadius: 4, padding: "2px 8px", fontWeight: 600 }}>{STATUS_LABEL[sel.status]}</span>
              <b>{sel.video?.dateiname ?? "Audio ohne Bild"}</b>
              {sel.video && <span style={{ color: MUTED }}>TC {sel.video.tc_start ?? "—"} ({sel.video.tc_quelle}{sel.video.ltc_kanal !== null ? `, Kanal ${sel.video.ltc_kanal}` : ""}) · {sel.video.fps ?? "?"} fps · {fmtDauer(sel.video.dauer_s)}{sel.video.scratch_kanal === null ? " · kein Scratch" : ` · Scratch Kanal ${sel.video.scratch_kanal}`}</span>}
              <div style={{ marginLeft: "auto", display: "flex", gap: 6, flexWrap: "wrap" }}>
                <button style={btn()} disabled={busy} onClick={() => void vorschau(sel.id)}>Vorschau erzeugen</button>
                <button style={btn(false, "#5fbf6a")} disabled={busy || sel.status === "manuell_bestaetigt"} onClick={() => void aktion(() => takeBestaetigen(sel.id), "Take bestätigt")}>Bestätigen</button>
                {sel.video && <button style={btn()} disabled={busy} title="Bewusst ohne Ton freigeben (Transkription auf Kamera-Ton)" onClick={() => void aktion(() => takeOhneAudioBestaetigen(sel.id), "Ohne Ton freigegeben")}>Ohne Ton freigeben</button>}
                <button style={btn(false, "#e2574a")} disabled={busy || sel.status === "manuell_abgelehnt"} onClick={() => void aktion(() => takeAblehnen(sel.id), "Take abgelehnt")}>Ablehnen</button>
                {sel.video && <button style={btn(false, "#7fb2ff")} disabled={busy || sel.status === "unklar" || sel.status === "manuell_abgelehnt"} onClick={() => void analyse(sel.id)}>Nur diesen Take analysieren</button>}
              </div>
            </div>

            {/* A/B-Player */}
            <ABPlayer videoUrl={mediaUrl(sel.vorschau_video_url)} audioUrl={mediaUrl(primaerLink?.vorschau_audio_url)} offsetS={offsetLive} audioName={primaerLink?.audio?.dateiname ?? null} />

            {/* Links */}
            {sel.links.map((l) => {
              const entwurf = offsetEntwurf[l.id] ?? l.offset_s;
              const geaendert = Math.abs(entwurf - l.offset_s) > 1e-6;
              return (
                <div key={l.id} style={{ background: PANEL2, borderRadius: 8, padding: 10, display: "flex", flexDirection: "column", gap: 6 }}>
                  <div style={{ display: "flex", gap: 8, alignItems: "center", flexWrap: "wrap" }}>
                    <b>♪ {l.audio?.dateiname}</b>
                    {l.audio && <span style={{ color: MUTED }}>TC {l.audio.tc_start ?? "—"} ({l.audio.tc_quelle}) · {l.audio.kanaele} Kanäle · Transkription Kanal {l.kanal_fuer_transkription}{l.audio.ixml && Array.isArray((l.audio.ixml as { tracks?: { index: number; name: string }[] }).tracks) ? ` („${((l.audio.ixml as { tracks: { index: number; name: string }[] }).tracks.find((t) => t.index === l.kanal_fuer_transkription + 1)?.name ?? "?")}“)` : ""} · {fmtDauer(l.audio.dauer_s)}</span>}
                    <span style={{ marginLeft: "auto", color: MUTED }}>{l.methode} · Konfidenz {(l.konfidenz * 100).toFixed(0)} %{l.bestaetigt ? " · ✓ bestätigt" : ""}</span>
                    <button style={btn(false, "#e2574a")} disabled={busy} title="Audio von diesem Take abhängen" onClick={() => void aktion(() => linkLoeschen(l.id), "Audio abgehängt")}>Abhängen</button>
                  </div>
                  <div style={{ color: TXT, lineHeight: 1.5 }}>{l.begruendung}</div>
                  {l.warnungen.map((w, i) => <div key={i} style={{ color: "#e0b84a" }}>⚠ {w}</div>)}
                  {l.methode !== "verwaist" && (
                    <div style={{ display: "flex", gap: 6, alignItems: "center", flexWrap: "wrap" }}>
                      <span style={{ color: MUTED }}>Offset (Audio − Video):</span>
                      {[-1, -0.1, -0.01].map((d) => <button key={d} style={btn()} onClick={() => setOffsetEntwurf((o) => ({ ...o, [l.id]: +(entwurf + d).toFixed(3) }))}>{d} s</button>)}
                      <input type="number" step="0.001" value={entwurf} onChange={(e) => setOffsetEntwurf((o) => ({ ...o, [l.id]: parseFloat(e.target.value) || 0 }))} style={{ ...inp, width: 100, fontVariantNumeric: "tabular-nums" }} />
                      {[0.01, 0.1, 1].map((d) => <button key={d} style={btn()} onClick={() => setOffsetEntwurf((o) => ({ ...o, [l.id]: +(entwurf + d).toFixed(3) }))}>+{d} s</button>)}
                      <button style={btn(geaendert, "#7fb2ff")} disabled={!geaendert || busy} onClick={() => void aktion(async () => { await linkOffsetSetzen(l.id, entwurf); setOffsetEntwurf((o) => { const c = { ...o }; delete c[l.id]; return c; }); }, "Offset gespeichert")}>Speichern</button>
                      {geaendert && <button style={btn()} onClick={() => setOffsetEntwurf((o) => { const c = { ...o }; delete c[l.id]; return c; })}>Zurücksetzen</button>}
                    </div>
                  )}
                </div>
              );
            })}

            {/* Kandidaten (unklar) */}
            {sel.kandidaten.length > 0 && (
              <div style={{ background: PANEL2, borderRadius: 8, padding: 10 }}>
                <b style={{ color: "#e2574a" }}>Kandidaten — nicht automatisch entschieden</b>
                {sel.kandidaten.map((k, i) => (
                  <div key={i} style={{ display: "flex", gap: 8, alignItems: "center", padding: "4px 0", borderTop: i ? `1px solid ${BORDER}` : "none" }}>
                    <div style={{ flex: 1 }}>
                      <div>♪ {k.audio_dateiname} ↔ {k.video_dateiname} · Überlappung {(k.ueberlappung_ratio * 100).toFixed(0)} % ({k.ueberlappung_s.toFixed(1)} s) · Offset {fmtOffset(k.offset_s)}</div>
                      <div style={{ color: MUTED }}>{k.begruendung}</div>
                    </div>
                    {sel.video && k.video_asset_id === sel.video_asset_id && (
                      <button style={btn(true, "#7fb2ff")} disabled={busy} onClick={() => void aktion(() => linkAnlegen(sel.id, k.audio_asset_id, k.offset_s), "Audio zugeordnet")}>Dieses Audio zuordnen</button>
                    )}
                  </div>
                ))}
              </div>
            )}

            {/* Rattacher */}
            {sel.video && (
              <div style={{ background: PANEL2, borderRadius: 8, padding: 10, display: "flex", gap: 8, alignItems: "center", flexWrap: "wrap" }}>
                <span style={{ color: MUTED }}>Anderes Audio anhängen:</span>
                <input placeholder="Audio suchen…" value={rattachSuche} onChange={(e) => setRattachSuche(e.target.value)} style={{ ...inp, width: 160 }} />
                <select value={rattachAudio} onChange={(e) => setRattachAudio(e.target.value)} style={{ ...inp, maxWidth: 360 }}>
                  <option value="">— wählen —</option>
                  {rattachListe.map((a) => <option key={a.id} value={a.id}>{a.dateiname} · {a.tc_start ?? "kein TC"} · {fmtDauer(a.dauer_s)}</option>)}
                </select>
                <button style={btn(!!rattachAudio, "#7fb2ff")} disabled={!rattachAudio || busy} title="Offset aus Timecode, sonst 0 s (im A/B-Player prüfen)"
                  onClick={() => void aktion(async () => { await linkAnlegen(sel.id, rattachAudio, null); setRattachAudio(""); }, "Audio angehängt (methode: manuell)")}>Anhängen</button>
              </div>
            )}

            {/* Warnungen */}
            {sel.warnungen.length > 0 && (
              <div style={{ background: PANEL2, borderRadius: 8, padding: 10 }}>
                <b>Hinweise</b>
                {sel.warnungen.map((w, i) => <div key={i} style={{ color: w.startsWith("Mehrdeutig") ? "#e2574a" : "#e0b84a", padding: "2px 0" }}>⚠ {w}</div>)}
              </div>
            )}
            {sel.video && sel.video.warnungen.length > 0 && (
              <div style={{ color: MUTED }}>{sel.video.warnungen.map((w, i) => <div key={i}>· {w}</div>)}</div>
            )}
          </>)}
