1	"use client";
2	
3	/**
4	 * CinAssist — Synchronisation (Validierung VOR der Analyse)
5	 *
6	 * Zwei Ordner (Kamera-Videos, Ton-WAVs) werden per Referenz importiert; der Matcher
7	 * (Timecode → Wellenform → Klappe → Dateiname) schlägt Takes vor. Diese Ansicht zeigt
8	 * jede Zuordnung mit Status, Methode, Offset und Begründung, lässt sie korrigieren
9	 * (anhängen / abhängen / Offset ±ms / bestätigen / ablehnen) und prüft sie im
10	 * A/B-Player (Bild + verknüpfter Ton mit Offset — der einzige echte Test).
11	 * „Analyse starten“ ist gesperrt, solange ein Take `unklar` ist.
12	 *
13	 * A/B-Player-Architektur: EIN Referenztakt (die `<video>`), das `<audio>` folgt mit
14	 * Schwellen-Drift-Korrektur (nie `currentTime` pro Frame; nur bei |Drift| > 80 ms).
15	 * Das ist ein Kontroll-Werkzeug, NICHT die NLE-Timeline (die hat ihre MasterClock).
16	 */
17	
18	import { useCallback, useEffect, useMemo, useRef, useState } from "react";
19	import {
20	  analyseStarten, connectJobWs, deleteImport, fetchAssets, fetchImporte, fetchTakes, importOrdner,
21	  linkAnlegen, linkLoeschen, linkOffsetSetzen, mediaUrl, runSync, takeAblehnen, takeBestaetigen,
22	  takeOhneAudioBestaetigen, vorschauAnfordern,
23	  type JobUpdate, type MediaAssetDTO, type OrdnerImportDTO, type TakeDTO, type TakeStatus,
24	} from "@/lib/api";
25	
26	// ─── Farben / Hilfen ─────────────────────────────────────
27	
28	const STATUS_FARBE: Record<TakeStatus, string> = {
29	  sicher: "#5fbf6a", plausibel: "#e0b84a", unklar: "#e2574a", verwaist: "#7a7a7a",
30	  manuell_bestaetigt: "#7fb2ff", manuell_abgelehnt: "#555",
31	};
32	const STATUS_LABEL: Record<TakeStatus, string> = {
33	  sicher: "sicher", plausibel: "plausibel", unklar: "unklar", verwaist: "verwaist",
34	  manuell_bestaetigt: "bestätigt", manuell_abgelehnt: "abgelehnt",
35	};
36	const BG = "#0f0f10", PANEL = "#1c1c1e", PANEL2 = "#242426", BORDER = "#2a2a2e", TXT = "#cfcfcf", MUTED = "#8a8a8a", ACCENT = "#b9d94a";
37	
38	const btn = (aktiv = false, farbe = ACCENT): React.CSSProperties => ({
39	  background: aktiv ? farbe : PANEL2, color: aktiv ? "#000" : TXT, border: `1px solid ${aktiv ? farbe : BORDER}`,
40	  borderRadius: 6, padding: "5px 10px", fontSize: 12, cursor: "pointer", fontWeight: aktiv ? 600 : 400,
41	});
42	const inp: React.CSSProperties = { background: "#111", color: TXT, border: `1px solid ${BORDER}`, borderRadius: 6, padding: "5px 8px", fontSize: 12 };
43	
44	function fmtOffset(s: number | null | undefined): string {
45	  if (s === null || s === undefined) return "—";
46	  return `${s >= 0 ? "+" : "−"}${Math.abs(s).toFixed(3)} s`;
47	}
48	function fmtDauer(s: number | null | undefined): string {
49	  if (!s && s !== 0) return "—";
50	  const m = Math.floor(s / 60), r = s - m * 60;
51	  return `${m}:${r.toFixed(1).padStart(4, "0")}`;
52	}
53	function gruppenKey(t: TakeDTO): string {
54	  return `${t.szene ?? "?"}|${t.plan ?? "?"}`;
55	}
56	function gruppenLabel(t: TakeDTO): string {
57	  return `Szene ${t.szene ?? "?"} · Einstellung ${t.plan ?? "?"}`;
58	}
59	
60	// ─── A/B-Player ──────────────────────────────────────────
61	
62	function ABPlayer({ videoUrl, audioUrl, offsetS, audioName }: {
63	  videoUrl: string | null; audioUrl: string | null; offsetS: number; audioName: string | null;
64	}) {
65	  const vRef = useRef<HTMLVideoElement>(null);
66	  const aRef = useRef<HTMLAudioElement>(null);
67	  const [mode, setMode] = useState<"A" | "B">("B");
68	  const [readout, setReadout] = useState({ v: 0, a: 0, drift: 0 });
69	  const offsetRef = useRef(offsetS);
70	  const modeRef = useRef(mode);
71	  useEffect(() => { offsetRef.current = offsetS; }, [offsetS]);
72	  useEffect(() => { modeRef.current = mode; }, [mode]);
73	
74	  useEffect(() => {
75	    let raf = 0;
76	    const tick = () => {
77	      const v = vRef.current, a = aRef.current;
78	      if (v && a) {
79	        // offset = audio_start − video_start  ⇒  audio_time = video_time − offset
80	        const ziel = v.currentTime - offsetRef.current;
81	        const imBereich = ziel >= 0 && (!isFinite(a.duration) || ziel < a.duration);
82	        v.muted = modeRef.current === "B";
83	        a.muted = modeRef.current === "A";
84	        if (v.paused || v.ended || !imBereich) {
85	          if (!a.paused) a.pause();
