91	        }
92	        setReadout({ v: v.currentTime, a: a.currentTime, drift: imBereich ? a.currentTime - ziel : 0 });
93	      }
94	      raf = requestAnimationFrame(tick);
95	    };
96	    raf = requestAnimationFrame(tick);
97	    return () => cancelAnimationFrame(raf);
98	  }, []);
99	
100	  if (!videoUrl) return <div style={{ color: MUTED, fontSize: 12 }}>Keine Video-Vorschau — „Vorschau erzeugen“ klicken.</div>;
101	  return (
102	    <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
103	      <video ref={vRef} src={videoUrl} controls playsInline style={{ width: "100%", maxHeight: 300, background: "#000", borderRadius: 6 }} />
104	      {audioUrl && <audio ref={aRef} src={audioUrl} preload="auto" />}
105	      <div style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 12 }}>
106	        <span style={{ color: MUTED }}>Ton:</span>
107	        <button style={btn(mode === "A")} onClick={() => setMode("A")}>A — Kamera</button>
108	        <button style={btn(mode === "B")} onClick={() => setMode("B")} disabled={!audioUrl} title={audioUrl ? "" : "kein verknüpftes Audio"}>
109	          B — verknüpft{audioName ? ` (${audioName})` : ""}
110	        </button>
111	        <span style={{ marginLeft: "auto", color: MUTED, fontVariantNumeric: "tabular-nums" }}>
112	          Video {readout.v.toFixed(2)} s · Audio {readout.a.toFixed(2)} s · Drift {(readout.drift * 1000).toFixed(0)} ms
113	        </span>
114	      </div>
115	    </div>
116	  );
117	}
118	
119	// ─── Haupt-Panel ─────────────────────────────────────────
120	
121	export default function SyncPanel({ onAnalyseGestartet }: { onAnalyseGestartet?: () => void }) {
