1	"use client";
2	
3	/**
4	 * CinAssist — Synchronisation (Validierung VOR der Analyse) — geführter Ablauf in 3 Schritten
5	 *
6	 *   1  Ordner wählen      Kamera-Videos + Ton-WAVs per Referenz (Ordner-Browser, keine Kopie)
7	 *   2  Synchronisieren    Kaskade Timecode → Wellenform → Klappe → Dateiname (läuft nach Import automatisch)
8	 *   3  Prüfen & Analyse   jede Zuordnung mit Status/Methode/Offset/Begründung, A/B-Player,
9	 *                         Korrekturen; „Analyse starten“ erst, wenn kein Take mehr `unklar` ist
10	 *
11	 * A/B-Player: EIN Referenztakt (die `<video>`), das `<audio>` folgt mit Schwellen-Drift-Korrektur
12	 * (nie `currentTime` pro Frame). Kontroll-Werkzeug, NICHT die NLE-Timeline (die hat ihre MasterClock).
13	 */
14	
15	import { useCallback, useEffect, useMemo, useRef, useState } from "react";
16	import {
17	  analyseStarten, connectJobWs, deleteImport, durchsucheOrdner, fetchAssets, fetchImporte, fetchTakes,
18	  importOrdner, linkAnlegen, linkLoeschen, linkOffsetSetzen, mediaUrl, runSync, takeAblehnen,
19	  takeBestaetigen, takeOhneAudioBestaetigen, vorschauAnfordern,
20	  type JobUpdate, type MediaAssetDTO, type OrdnerEintrag, type OrdnerImportDTO, type OrdnerListe,
21	  type TakeDTO, type TakeStatus,
22	} from "@/lib/api";
23	
24	// ─── Farben / Hilfen ─────────────────────────────────────
25	
26	const STATUS_FARBE: Record<TakeStatus, string> = {
27	  sicher: "#5fbf6a", plausibel: "#e0b84a", unklar: "#e2574a", verwaist: "#7a7a7a",
28	  manuell_bestaetigt: "#7fb2ff", manuell_abgelehnt: "#555",
29	};
30	const STATUS_LABEL: Record<TakeStatus, string> = {
31	  sicher: "sicher", plausibel: "plausibel", unklar: "unklar", verwaist: "verwaist",
32	  manuell_bestaetigt: "bestätigt", manuell_abgelehnt: "abgelehnt",
33	};
34	const STATUS_ERKLAERUNG: Record<TakeStatus, string> = {
35	  sicher: "Timecode beider Geräte überlappt zu > 80 % — kein Handlungsbedarf, Analyse möglich.",
36	  plausibel: "Teil-Überlappung oder nur Wellenform/Klappe — im A/B-Player kurz gegenhören.",
37	  unklar: "Mehrere Kandidaten — bitte entscheiden (Audio zuordnen, ohne Ton freigeben oder ablehnen). Blockiert die Analyse.",
38	  verwaist: "Kein Partner gefunden (Bild ohne Ton oder Ton ohne Bild). Kann so analysiert werden (Kamera-Ton) oder manuell verknüpft werden.",
39	  manuell_bestaetigt: "Von dir bestätigt.",
40	  manuell_abgelehnt: "Von dir ausgeschlossen — wird nicht analysiert.",
41	};
42	const PANEL = "#1c1c1e", PANEL2 = "#242426", BORDER = "#2a2a2e", TXT = "#cfcfcf", MUTED = "#8a8a8a", ACCENT = "#b9d94a";
43	
44	const btn = (aktiv = false, farbe = ACCENT, disabled = false): React.CSSProperties => ({
45	  background: aktiv ? farbe : PANEL2, color: aktiv ? "#000" : TXT, border: `1px solid ${aktiv ? farbe : BORDER}`,
46	  borderRadius: 6, padding: "6px 11px", fontSize: 12, cursor: disabled ? "not-allowed" : "pointer",
47	  fontWeight: aktiv ? 600 : 400, opacity: disabled ? 0.38 : 1,
48	});
49	const inp: React.CSSProperties = { background: "#111", color: TXT, border: `1px solid ${BORDER}`, borderRadius: 6, padding: "6px 8px", fontSize: 12 };
50	const karte: React.CSSProperties = { background: PANEL, border: `1px solid ${BORDER}`, borderRadius: 10, padding: 12 };
51	
52	function fmtOffset(s: number | null | undefined): string {
53	  if (s === null || s === undefined) return "—";
54	  return `${s >= 0 ? "+" : "−"}${Math.abs(s).toFixed(3)} s`;
55	}
56	function fmtDauer(s: number | null | undefined): string {
57	  if (!s && s !== 0) return "—";
58	  const m = Math.floor(s / 60), r = s - m * 60;
59	  return `${m}:${r.toFixed(1).padStart(4, "0")}`;
60	}
61	function gruppenKey(t: TakeDTO): string { return `${t.szene ?? "?"}|${t.plan ?? "?"}`; }
62	function gruppenLabel(t: TakeDTO): string { return `Szene ${t.szene ?? "?"} · Einstellung ${t.plan ?? "?"}`; }
63	function kurzPfad(p: string): string { const t = p.split("/").filter(Boolean); return t.length > 3 ? "…/" + t.slice(-3).join("/") : p; }
64	
65	/** Kleiner Schritt-Chip: 1/2/3 mit Zustand. */
66	function Schritt({ nr, label, zustand }: { nr: number; label: string; zustand: "offen" | "aktiv" | "fertig" }) {
67	  const col = zustand === "fertig" ? "#5fbf6a" : zustand === "aktiv" ? ACCENT : MUTED;
68	  return (
69	    <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
70	      <span style={{ width: 22, height: 22, borderRadius: 11, background: zustand === "offen" ? "transparent" : col, border: `1px solid ${col}`,
71	        color: zustand === "offen" ? col : "#000", display: "inline-flex", alignItems: "center", justifyContent: "center", fontWeight: 700, fontSize: 12 }}>
72	        {zustand === "fertig" ? "✓" : nr}
73	      </span>
74	      <span style={{ color: zustand === "offen" ? MUTED : TXT, fontWeight: zustand === "aktiv" ? 600 : 400 }}>{label}</span>
75	    </div>
76	  );
77	}
78	
79	// ─── Ordner-Browser (Modal) ──────────────────────────────
80	
81	function OrdnerBrowser({ typ, onWahl, onSchliessen }: {
