            schritt="transkription",
            schritt_daten={"segmente": 0, "woerter": 0, "sprache": "—", "preview": "(stumm)", "modell": "skipped"},
        )
        return {"text": "", "sprache": "de", "segmente": []}

    try:
        import mlx_whisper

