export function framesToSeconds(f: Frames, fps: number): number {
  return f / fps;
}

/** Display timecode `HH:MM:SS:FF`. */
export function framesToTimecode(f: Frames, fps: number): string {
  const fpsInt = Math.max(1, Math.round(fps));
  const total = Math.max(0, Math.floor(f));
  const ff = total % fpsInt;
  const ss = Math.floor(total / fpsInt) % 60;
  const mm = Math.floor(total / (fpsInt * 60)) % 60;
  const hh = Math.floor(total / (fpsInt * 3600));
  const pad = (n: number) => String(n).padStart(2, "0");
  return `${pad(hh)}:${pad(mm)}:${pad(ss)}:${pad(ff)}`;
}

// ─── Adapter from the existing seconds-based Editor model ──────────

/**
 * Mirror of the TLClip shape in `src/components/Editor.tsx` (seconds-based).
 * Re-defined here so lib/ never reaches up into components/. Field names are
 * identical, so the Editor's TLClip is structurally assignable to this type.
 */
export type TLClip = {
  tlId: string;
  clipId: string;
  start: number;      // seconds on timeline
  mediaStart: number; // seconds into source
  duration: number;   // seconds
  name?: string;
  proxyUrl?: string | null;
  videoUrl?: string | null;
  sourceDuration?: number;
  /** Whether the clip carries an audio stream (drives the audio track split). */
  hasAudio?: boolean;
  /** Which video track this clip lives on (0 = V1 = top priority). Default 0. */
  videoTrackIndex?: number;
  /** Which audio track this clip's audio lives on. Defaults to videoTrackIndex. */
  audioTrackIndex?: number;
  /** Fade-in ramp length (seconds). Applied to opacity + volume. */
  fadeIn?: number;
  /** Fade-out ramp length (seconds). Applied to opacity + volume. */
  fadeOut?: number;
  /** Fade-in curve shape in [-1, 1]. 0 = linear. */
  fadeInCurve?: number;
  /** Fade-out curve shape in [-1, 1]. 0 = linear. */
  fadeOutCurve?: number;
  /** Clip-level gain in dB (rubber band). 0 dB = unity. */
  gainDb?: number;
};

    this.clock.seek(frame);
  }

  private scrubTimer: number | null = null;

  /**
   * Scrub audio kick — briefly plays the active <video> for `ms` milliseconds
   * without touching the master clock. Called from the UI's mousemove during a
   * playhead drag to let the user hear the audio at the scrubbed position.
   * Safe to call rapidly: subsequent kicks reset the auto-pause timer.
   */
  scrubAudioKick(ms: number = 80) {
    const v = this.pool.active;
    if (!v || v.readyState < 2) return;
    if (this.masterMuted) return;
    // Unmute + master volume (no fade/gain multipliers during scrub — safest).
    v.muted = false;
    v.volume = this.masterVolume;
    v.play().catch(() => {});
    if (this.scrubTimer !== null) window.clearTimeout(this.scrubTimer);
    this.scrubTimer = window.setTimeout(() => {
      if (this.pool.active === v && !this.clock.playing) v.pause();
      this.scrubTimer = null;
    }, ms);
  }

  /**
   * Push per-track UI state (hidden/solo/mute), keyed by video-track id. The
   * map is stored wholesale (consumers build a fresh Map each change) and the
   * current frame is re-rendered so a visibility/mute toggle takes effect
   * immediately, even while paused.
   */
  setTrackStates(
    map: Map<string, { hidden?: boolean; solo?: boolean; mute?: boolean }>,
  ) {
    this.trackStates = map;
    this.render(this.clock.currentFrame);
  }

  /** Master playback volume + mute (from the UI transport / Ton tab). */
  setMasterAudio(volume: number, muted: boolean) {
    this.masterVolume = volume;
    this.masterMuted = muted;
    this.render(this.clock.currentFrame);
  }

  /** The <video> element currently emitting audio (used by VU meter). */
  getUnmutedElement(): HTMLVideoElement | null {
    return this.pool.getUnmutedElement();
  }

