254	function OverviewTab({ analyse, pipeline }: { analyse: Analyse; pipeline: Pipeline | null }) {
255	  const totalTranscribed = analyse.szenen.filter((s) => s.transkription).length;
256	  const withEmbedding = analyse.szenen.filter((s) => s.hat_embedding).length;
257	  const withDescription = analyse.szenen.filter((s) => s.beschreibung).length;
258	  const durMinutes = (analyse.dauer / 60).toFixed(1);
259	  const cards = [
260	    { label: "Dauer", value: `${durMinutes} min`, sub: fmtSec(analyse.dauer) },
261	    { label: "Auflösung", value: analyse.aufloesung ?? "?", sub: `${analyse.bildrate ?? "?"} fps` },
262	    { label: "Szenen erkannt", value: String(analyse.szenen_anzahl), sub: "scenedetect" },
263	    { label: "Transkribiert", value: `${totalTranscribed}/${analyse.szenen_anzahl}`, sub: "mlx-whisper" },
264	    { label: "CLIP-Embeddings", value: `${withEmbedding}/${analyse.szenen_anzahl}`, sub: "open_clip" },
265	    { label: "Beschreibungen", value: `${withDescription}/${analyse.szenen_anzahl}`, sub: "moondream · llama3" },
266	  ];
267	  return (
268	    <div>
269	      <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 10, marginBottom: 18 }}>
270	        {cards.map((c) => (
271	          <div key={c.label} style={{ background: "#1c1c1e", border: "1px solid rgba(255,255,255,0.05)", borderRadius: 8, padding: "12px 14px" }}>
272	            <div style={{ fontSize: 10, color: "#7a7a7a", textTransform: "uppercase", letterSpacing: 0.5 }}>{c.label}</div>
273	            <div style={{ fontSize: 18, fontWeight: 600, marginTop: 4, color: "#f0f0f0" }}>{c.value}</div>
274	            <div style={{ fontSize: 10, color: "#666", marginTop: 2 }}>{c.sub}</div>
275	          </div>
276	        ))}
277	      </div>
278	      {pipeline && (
279	        <div style={{ background: "#1c1c1e", borderRadius: 8, padding: 14 }}>
280	          <div style={{ fontSize: 11, color: "#8a8a8a", textTransform: "uppercase", letterSpacing: 0.5, marginBottom: 8 }}>Pipeline-Schritte</div>
281	          <div style={{ display: "flex", flexWrap: "wrap", gap: 6 }}>
282	            {Object.keys(pipeline.schritt_history).map((k) => (
283	              <span key={k} style={{ padding: "4px 10px", borderRadius: 12, background: "rgba(120,200,120,0.13)", border: "1px solid rgba(120,200,120,0.3)", fontSize: 11, color: "#96d996" }}>✓ {k}</span>
284	            ))}
285	          </div>
286	        </div>
287	      )}
288	    </div>
289	  );
290	}
