292	function ScenesTab({ szenen }: { szenen: Szene[] }) {
293	  if (szenen.length === 0) return <div style={{ color: "#888" }}>Keine Szenen erkannt.</div>;
294	  // Reconstruit la transcription de chaque scène en NE prenant QUE les segments
295	  // dont le `start` tombe dans le range [s.start, s.end] — évite les doublons
296	  // dus au pipeline d'ingest qui attribue un même segment Whisper à plusieurs
297	  // scènes qu'il traverse.
298	  const trueTranscript = (s: Szene): string => {
299	    const raw = s.transkription_json;
300	    if (!Array.isArray(raw)) return "";
301	    const parts: string[] = [];
302	    for (const seg of raw) {
303	      if (!seg || typeof seg !== "object") continue;
304	      const w = seg as WhisperSegment;
305	      if (typeof w.start !== "number" || typeof w.text !== "string") continue;
306	      if (isHallucination(w.text)) continue;
307	      if (w.start >= s.start && w.start < s.end) parts.push(w.text.trim());
308	    }
309	    return parts.join(" ").trim();
310	  };
311	  return (
312	    <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
313	      {szenen.map((s) => {
314	        const txt = trueTranscript(s);
315	        return (
316	          <div key={s.id} style={{ display: "flex", gap: 12, padding: 10, background: "#1c1c1e", borderRadius: 8, border: "1px solid rgba(255,255,255,0.05)" }}>
317	            {(() => {
318	              const u = thumbUrl(s.thumbnail_pfad);
319	              return u ? (
320	                <img src={u} alt="" style={{ width: 120, height: 68, objectFit: "cover", borderRadius: 4, flexShrink: 0, background: "#000" }} />
321	              ) : (
322	                <div style={{ width: 120, height: 68, background: "#0e0e10", borderRadius: 4, flexShrink: 0, display: "flex", alignItems: "center", justifyContent: "center", color: "#555", fontSize: 10 }}>kein Frame</div>
323	              );
324	            })()}
325	            <div style={{ flex: 1, minWidth: 0 }}>
326	              <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 4 }}>
327	                <span style={{ fontSize: 12, fontWeight: 600, color: "#e5c100" }}>Szene {s.szenen_nr}</span>
328	                <span style={{ fontSize: 10, color: "#888", fontFamily: "ui-monospace, monospace" }}>{fmtSec(s.start)} → {fmtSec(s.end)} · {s.dauer.toFixed(2)}s</span>
329	                {s.hat_embedding && <span style={{ fontSize: 9, padding: "1px 6px", borderRadius: 8, background: "rgba(120,180,255,0.15)", color: "#9ac2ff" }}>CLIP</span>}
330	              </div>
331	              {s.beschreibung && (
332	                <div style={{ fontSize: 12, color: "#d0d0d0", lineHeight: 1.4, marginBottom: 4 }}>{s.beschreibung}</div>
333	              )}
334	              {txt ? (
335	                <div style={{ fontSize: 11, color: "#8a8a8a", fontStyle: "italic", lineHeight: 1.35, borderLeft: "2px solid rgba(229,193,0,0.35)", paddingLeft: 8, marginTop: 4 }}>
336	                  „{txt.length > 220 ? txt.slice(0, 220) + "…" : txt}"
337	                </div>
338	              ) : (
339	                <div style={{ fontSize: 10, color: "#555", fontStyle: "italic", marginTop: 4 }}>Keine Sprache in dieser Szene.</div>
340	              )}
341	            </div>
342	          </div>
343	        );
344	      })}
345	    </div>
346	  );
347	}
348	
