  /** Legacy champ (avant scission) — merged côté frontend en anwesende. */
  personen?: string[];
  generated_at?: string;
  model?: string;
};

const fmtSec = (s: number) => {
  const m = Math.floor(s / 60);
  const rest = s - m * 60;
  return `${String(m).padStart(2, "0")}:${rest.toFixed(2).padStart(5, "0")}`;
};

/**
