                  <div style={{ fontSize: 12, color: "#e0e0e0", lineHeight: 1.4 }}>{anwesend.length ? anwesend.join(", ") : "—"}</div>
                </div>
                <div style={{ background: "#1c1c1e", borderRadius: 8, padding: "10px 12px", border: "1px solid rgba(180,180,255,0.15)" }}>
