            gesamt = sum(len(s) for s in saetze) or 1
            t = s0
            for s in saetze:
                d = (s1 - s0) * len(s) / gesamt
                out.append(Einheit(t, t + d, s.strip(), sprecher))
                t += d
    for e in out:
        e.art = klassifiziere_einheit(e.text)
    return out


