        <div style={{
          position: "fixed", left: 18, right: 386, bottom: 66, height: 260,
          background: "rgba(15,15,17,0.96)", backdropFilter: "blur(6px)",
          border: "1px solid #2a2a2e", borderRadius: 12, padding: 20,
          display: "flex", flexDirection: "column", gap: 12,
          boxShadow: "0 20px 60px rgba(0,0,0,.6)", zIndex: 90,
        }}>
          <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
export function connectJobWs(
  jobId: string,
  onMessage: (data: JobUpdate) => void,
  onClose?: () => void,
): WebSocket {
  const ws = new WebSocket(`${resolveWsBase()}/ws/jobs/${encodeURIComponent(jobId)}`);
  ws.onmessage = (e) => {
    try {
      onMessage(JSON.parse(e.data));
    } catch { /* ignore bad json */ }
  };
  ws.onclose = () => onClose?.();
